(function(){let prompt=null,ua=navigator.userAgent,ios=/iPhone|iPad|iPod/.test(ua)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1,android=/Android/.test(ua),$=id=>document.getElementById(id);$('device').textContent=ios?'iPhone / iPad':android?'Android':'휴대폰에서 이 주소를 열어주세요';$('guide').textContent=ios?'Safari의 공유 버튼 → 홈 화면에 추가 → 추가를 선택하세요.':android?'Chrome 메뉴 → 앱 설치 또는 홈 화면에 추가를 선택하세요.':'Android Chrome 또는 iPhone Safari에서 설치할 수 있습니다.';window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e});$('pwa').onclick=async()=>{if(prompt){await prompt.prompt();prompt=null}else $('guide').style.color='#ffe3a6'};$('status').textContent=location.protocol==='https:'?'무료 홈 화면 설치형 게임입니다. Android와 iPhone에서 이용할 수 있습니다.':'파일 체험 모드입니다. HTTPS 배포 주소에서 홈 화면에 설치해 주세요.';})();
